"use client";

import { useState } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { useAuth } from "@/contexts/AuthContext";
import { 
  Menu, X, Wallet, ShoppingBag, Home, 
  LogOut, ChevronRight, User
} from "lucide-react";

export default function Navbar() {
  const [isOpen, setIsOpen] = useState(false);
  const { user, userData, logout } = useAuth();
  const pathname = usePathname();

  const navLinks = [
    { name: "Trang chủ", href: "/", icon: Home },
    { name: "Sản phẩm", href: "/product", icon: ShoppingBag },
    { name: "Ví & Nạp tiền", href: "/wallet", icon: Wallet },
  ];

  return (
    <>
      {/* THANH MENU PHÍA TRÊN (TOP NAVBAR) */}
      <header className="sticky top-0 z-50 bg-slate-900/90 backdrop-blur-md border-b border-slate-800 text-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            
            {/* LOGO */}
            <Link href="/" className="flex items-center gap-2">
              <span className="bg-gradient-to-r from-blue-500 to-indigo-500 text-white font-black px-3 py-1.5 rounded-xl text-lg tracking-wider shadow-lg shadow-blue-500/20">
                DoKhai
              </span>
              <span className="font-extrabold text-xl tracking-tight text-slate-100">Shop</span>
            </Link>

            {/* NAV LINKS CHO MÁY TÍNH (DESKTOP) */}
            <nav className="hidden md:flex items-center gap-6">
              {navLinks.map((link) => {
                const isActive = pathname === link.href;
                return (
                  <Link
                    key={link.href}
                    href={link.href}
                    className={`text-sm font-semibold transition-colors flex items-center gap-2 ${
                      isActive ? "text-blue-400" : "text-slate-300 hover:text-white"
                    }`}
                  >
                    <link.icon className="w-4 h-4" />
                    {link.name}
                  </Link>
                );
              })}
            </nav>

            {/* TÀI KHOẢN & VÍ CHO MÁY TÍNH */}
            <div className="hidden md:flex items-center gap-4">
              {user ? (
                <div className="flex items-center gap-3">
                  <Link
                    href="/wallet"
                    className="bg-slate-800 hover:bg-slate-700/80 border border-slate-700 px-3.5 py-1.5 rounded-xl text-sm font-bold text-emerald-400 flex items-center gap-2 transition"
                  >
                    <Wallet className="w-4 h-4 text-emerald-400" />
                    {(userData?.wallet || 0).toLocaleString("vi-VN")}đ
                  </Link>

                  <div className="flex items-center gap-2 bg-slate-800/80 px-3 py-1.5 rounded-xl border border-slate-700 text-sm">
                    <img
                      src={user.photoURL || "https://api.dicebear.com/7.x/bottts/svg?seed=Dokhai"}
                      alt={user.displayName || "User"}
                      className="w-7 h-7 rounded-full border border-blue-500"
                    />
                    <span className="font-semibold text-slate-200 max-w-[120px] truncate">
                      {user.displayName}
                    </span>
                    <button
                      onClick={logout}
                      title="Đăng xuất"
                      className="text-slate-400 hover:text-rose-400 ml-1 transition"
                    >
                      <LogOut className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              ) : (
                <Link
                  href="/auth/login"
                  className="bg-blue-600 hover:bg-blue-500 font-bold text-sm px-5 py-2 rounded-xl text-white transition shadow-lg shadow-blue-600/30"
                >
                  Đăng nhập
                </Link>
              )}
            </div>

            {/* NÚT HAMBURGER CHO ĐIỆN THOẠI */}
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="md:hidden p-2 rounded-xl text-slate-300 hover:bg-slate-800 transition"
              aria-label="Toggle menu"
            >
              {isOpen ? <X className="w-6 h-6 text-blue-400" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>

        {/* MENU XỔ XUỐNG KHI BẤM HAMBURGER TRÊN ĐIỆN THOẠI */}
        {isOpen && (
          <div className="md:hidden bg-slate-900 border-b border-slate-800 px-4 pt-3 pb-6 space-y-3">
            {/* Khung thông tin User trên Mobile */}
            {user ? (
              <div className="bg-slate-800/80 p-3.5 rounded-2xl border border-slate-700 flex items-center justify-between mb-2">
                <div className="flex items-center gap-3">
                  <img
                    src={user.photoURL || "https://api.dicebear.com/7.x/bottts/svg?seed=Dokhai"}
                    alt={user.displayName || "User"}
                    className="w-10 h-10 rounded-full border border-blue-500"
                  />
                  <div>
                    <p className="font-bold text-sm text-slate-100">{user.displayName}</p>
                    <p className="text-xs font-bold text-emerald-400 flex items-center gap-1">
                      <Wallet className="w-3.5 h-3.5" />
                      {(userData?.wallet || 0).toLocaleString("vi-VN")}đ
                    </p>
                  </div>
                </div>
                <button
                  onClick={() => {
                    logout();
                    setIsOpen(false);
                  }}
                  className="p-2 bg-rose-500/10 text-rose-400 rounded-xl hover:bg-rose-500/20 text-xs font-bold transition flex items-center gap-1"
                >
                  <LogOut className="w-4 h-4" />
                </button>
              </div>
            ) : (
              <Link
                href="/auth/login"
                onClick={() => setIsOpen(false)}
                className="block text-center w-full bg-blue-600 hover:bg-blue-500 text-white font-bold py-3 rounded-2xl shadow-lg transition"
              >
                Đăng nhập Google
              </Link>
            )}

            {/* Các liên kết điều hướng */}
            <div className="space-y-1">
              {navLinks.map((link) => {
                const isActive = pathname === link.href;
                return (
                  <Link
                    key={link.href}
                    href={link.href}
                    onClick={() => setIsOpen(false)}
                    className={`flex items-center justify-between px-4 py-3 rounded-xl font-semibold text-sm transition ${
                      isActive
                        ? "bg-blue-600/20 text-blue-400 border border-blue-500/30"
                        : "text-slate-300 hover:bg-slate-800"
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <link.icon className="w-5 h-5 text-blue-400" />
                      <span>{link.name}</span>
                    </div>
                    <ChevronRight className="w-4 h-4 text-slate-500" />
                  </Link>
                );
              })}
            </div>
          </div>
        )}
      </header>

      {/* THANH ĐIỀU HƯỚNG CỐ ĐỊNH Ở ĐÁY MÀN HÌNH ĐIỆN THOẠI (BOTTOM NAV) */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 z-50 bg-slate-900/95 backdrop-blur-lg border-t border-slate-800 px-6 py-2 shadow-2xl">
        <div className="flex items-center justify-around">
          {navLinks.map((link) => {
            const isActive = pathname === link.href;
            return (
              <Link
                key={link.href}
                href={link.href}
                className={`flex flex-col items-center gap-1 py-1 transition ${
                  isActive ? "text-blue-400 font-bold" : "text-slate-400 hover:text-slate-200"
                }`}
              >
                <link.icon className={`w-5 h-5 ${isActive ? "text-blue-400 scale-110" : ""}`} />
                <span className="text-[11px]">{link.name}</span>
              </Link>
            );
          })}
        </div>
      </div>
    </>
  );
}